{
  "ruleset_id": "kulturnyy-grant-gorodskaya-stsena",
  "rules": [
    {
      "description": "Руководитель проекта должен быть совершеннолетним: возраст не менее 18 лет.",
      "severity": "critical",
      "category": "возраст руководителя",
      "condition": {
        "field": "team.project_lead_age",
        "op": "ge",
        "value": 18
      }
    },
    {
      "description": "Заявитель должен обеспечить не менее 20% бюджета за счёт софинансирования.",
      "severity": "critical",
      "category": "софинансирование",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "Для очных мероприятий требуется согласие площадки.",
      "severity": "critical",
      "category": "согласие площадки",
      "condition": {
        "field": "documents.venue_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Запрашиваемый грант не должен превышать 1 500 000 рублей.",
      "severity": "critical",
      "category": "размер гранта",
      "condition": {
        "field": "application.requested_rub",
        "op": "le",
        "value": 1500000
      }
    }
  ]
}

{
  "ruleset_id": "programma-dopolnitelnogo-obrazovaniya",
  "rules": [
    {
      "description": "Организация должна предоставить лицензию на образовательную деятельность.",
      "severity": "critical",
      "category": "лицензирование",
      "condition": {
        "field": "documents.education_license.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Объём программы должен составлять не менее 72 часов.",
      "severity": "critical",
      "category": "объём программы",
      "condition": {
        "field": "curriculum.total_hours",
        "op": "ge",
        "value": 72
      }
    },
    {
      "description": "Не менее 80% преподавателей должны иметь профильную квалификацию.",
      "severity": "critical",
      "category": "квалификация преподавателей",
      "condition": {
        "field": "staff.qualified_teachers_pct",
        "op": "ge",
        "value": 80
      }
    },
    {
      "description": "Формат реализации программы должен быть только «очно» или «смешанно».",
      "severity": "critical",
      "category": "формат реализации",
      "condition": {
        "field": "programme.delivery_format",
        "op": "in",
        "value": [
          "очно",
          "смешанно"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "subsidy-energy-efficiency",
  "rules": [
    {
      "description": "Проект должен снизить потребление энергии не менее чем на 20%.",
      "severity": "critical",
      "category": "энергоэффективность",
      "condition": {
        "field": "project.energy_consumption_reduction_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "Доля софинансирования заявителя должна составлять не менее 30%.",
      "severity": "critical",
      "category": "софинансирование",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 30
      }
    },
    {
      "description": "К заявке должен быть приложен технический паспорт объекта.",
      "severity": "critical",
      "category": "документы",
      "condition": {
        "field": "documents.technical_passport.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Работы должны быть завершены не позднее 31 декабря 2027 года.",
      "severity": "critical",
      "category": "срок выполнения",
      "condition": {
        "field": "project.completion_date",
        "op": "le",
        "value": "2027-12-31"
      }
    }
  ]
}

{
  "ruleset_id": "nordstar-main-track-v2-4",
  "rules": [
    {
      "description": "Заявитель основного трека должен быть зарегистрирован не менее 24 месяцев.",
      "severity": "critical",
      "category": "допуск",
      "condition": {
        "field": "org_v2.months_registered",
        "op": "ge",
        "value": 24
      }
    },
    {
      "description": "Запрашиваемая сумма гранта основного трека не должна превышать 250000 евро.",
      "severity": "critical",
      "category": "лимит",
      "condition": {
        "field": "org_v2.total_requested",
        "op": "le",
        "value": 250000
      }
    },
    {
      "description": "К заявке должно быть приложено независимое аудиторское заключение за последний завершённый финансовый год.",
      "severity": "critical",
      "category": "аудит",
      "condition": {
        "field": "documents.audit_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Дата подачи заявки должна быть не позднее 31 марта 2027 года включительно.",
      "severity": "critical",
      "category": "срок",
      "condition": {
        "field": "org_v2.submission_date",
        "op": "le",
        "value": "2027-03-31"
      }
    },
    {
      "description": "Число сотрудников в заявке должно совпадать с численностью в годовом отчёте.",
      "severity": "major",
      "category": "согласованность",
      "condition": {
        "op": "consistent",
        "fields": [
          "org_v2.declared_headcount",
          "annual_report.headcount"
        ],
        "value": null
      }
    },
    {
      "description": "Годовой отчёт должен быть подготовлен по МСФО.",
      "severity": "minor",
      "category": "отчётность",
      "condition": {
        "field": "annual_report.ifrs",
        "op": "eq",
        "value": true
      }
    }
  ]
}

{
  "ruleset_id": "fond-primer-grant-program-2026",
  "rules": [
    {
      "description": "На дату подачи организация должна быть зарегистрирована не менее 12 месяцев.",
      "severity": "critical",
      "category": "допуск",
      "condition": {
        "field": "application_form.months_registered",
        "op": "lt",
        "value": 12
      }
    },
    {
      "description": "Запрашиваемая сумма не должна превышать 100000 евро.",
      "severity": "major",
      "category": "лимит бюджета",
      "condition": {
        "field": "application_form.requested_total_eur",
        "op": "gt",
        "value": 100000
      }
    },
    {
      "description": "Расходы на оборудование не должны превышать 40% общего бюджета.",
      "severity": "major",
      "category": "оборудование",
      "condition": {
        "field": "budget.row.equipment.share_pct",
        "op": "gt",
        "value": 40
      }
    },
    {
      "description": "Форма заявки должна присутствовать в полном пакете документов.",
      "severity": "critical",
      "category": "обязательные документы",
      "condition": {
        "field": "documents.application_form.present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Детализированный бюджет должен присутствовать в полном пакете документов.",
      "severity": "critical",
      "category": "обязательные документы",
      "condition": {
        "field": "documents.budget.present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Свидетельство о регистрации или выписка из реестра должны присутствовать в полном пакете документов.",
      "severity": "critical",
      "category": "обязательные документы",
      "condition": {
        "field": "documents.registration_cert.present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Последняя финансовая отчётность должна присутствовать в полном пакете документов.",
      "severity": "critical",
      "category": "обязательные документы",
      "condition": {
        "field": "documents.finance_statement.present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Заявка должна быть подана не позднее 1 октября 2026 года включительно.",
      "severity": "major",
      "category": "срок подачи",
      "condition": {
        "field": "application_form.submission_date",
        "op": "after",
        "value": "2026-10-01"
      }
    },
    {
      "description": "Форма заявки должна быть подписана законным представителем.",
      "severity": "critical",
      "category": "подпись",
      "condition": {
        "field": "application_form.signature_present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Запрашиваемая в форме сумма должна точно совпадать с итогом детализированного бюджета.",
      "severity": "major",
      "category": "согласованность",
      "condition": {
        "op": "consistent",
        "fields": [
          "application_form.requested_total_eur",
          "budget.totals.total"
        ]
      }
    },
    {
      "description": "Финансовая отчётность должна охватывать период FY2025.",
      "severity": "minor",
      "category": "отчётный период",
      "condition": {
        "field": "finance_statement.period",
        "op": "ne",
        "value": "FY2025"
      }
    }
  ]
}

{
  "ruleset_id": "programma-kapitalnogo-remonta",
  "rules": [
    {
      "description": "Дом должен быть построен не позднее 2005 года.",
      "severity": "critical",
      "category": "год строительства",
      "condition": {
        "field": "building.construction_year",
        "op": "le",
        "value": 2005
      }
    },
    {
      "description": "Решение собственников должно быть поддержано не менее чем 66% голосов.",
      "severity": "critical",
      "category": "одобрение собственников",
      "condition": {
        "field": "owners.approval_pct",
        "op": "ge",
        "value": 66
      }
    },
    {
      "description": "К заявке должен прилагаться акт обследования дефектов.",
      "severity": "critical",
      "category": "документы",
      "condition": {
        "field": "documents.defect_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявка должна быть подана до 1 апреля 2027 года включительно.",
      "severity": "critical",
      "category": "срок подачи",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2027-04-01"
      }
    }
  ]
}

{
  "ruleset_id": "preferential-microloan-for-smes",
  "rules": [
    {
      "description": "Годовая выручка компании не превышает 120000000 рублей.",
      "severity": "critical",
      "category": "выручка",
      "condition": {
        "field": "company.annual_revenue_rub",
        "op": "le",
        "value": 120000000
      }
    },
    {
      "description": "Просроченная задолженность отсутствует.",
      "severity": "critical",
      "category": "задолженность",
      "condition": {
        "field": "company.overdue_debt",
        "op": "eq",
        "value": 0
      }
    },
    {
      "description": "Не менее 51 процента долей принадлежит российским владельцам.",
      "severity": "critical",
      "category": "российское владение",
      "condition": {
        "field": "company.russian_ownership_pct",
        "op": "ge",
        "value": 51
      }
    },
    {
      "description": "Сумма займа не превышает 10000000 рублей.",
      "severity": "critical",
      "category": "сумма займа",
      "condition": {
        "field": "loan.requested_rub",
        "op": "le",
        "value": 10000000
      }
    }
  ]
}

{
  "ruleset_id": "municipal_subsidy_2026",
  "rules": [
    {
      "description": "Получатель должен быть зарегистрирован не менее 12 месяцев.",
      "severity": "critical",
      "category": "регистрация",
      "condition": {
        "field": "applicant.registration_months",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "Запрашиваемая субсидия не должна превышать 5 000 000 рублей.",
      "severity": "critical",
      "category": "сумма",
      "condition": {
        "field": "application.requested_rub",
        "op": "le",
        "value": 5000000
      }
    },
    {
      "description": "К заявке должна быть приложена финансовая отчётность за последний год.",
      "severity": "critical",
      "category": "документы",
      "condition": {
        "field": "documents.financial_statement.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявка должна быть подана не позднее 15 сентября 2026 года включительно.",
      "severity": "critical",
      "category": "срок подачи",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2026-09-15"
      }
    },
    {
      "description": "У организации не должно быть задолженности по налогам.",
      "severity": "critical",
      "category": "налоговая задолженность",
      "condition": {
        "field": "applicant.tax_arrears",
        "op": "eq",
        "value": 0
      }
    }
  ]
}

{
  "ruleset_id": "zakupka-remontnykh-rabot",
  "rules": [
    {
      "description": "Годовая выручка поставщика должна составлять не менее 10000000 рублей.",
      "severity": "critical",
      "category": "финансовый порог",
      "condition": {
        "field": "supplier.annual_turnover_rub",
        "op": "ge",
        "value": 10000000
      }
    },
    {
      "description": "Для допуска требуется действующее свидетельство СРО.",
      "severity": "critical",
      "category": "допуск",
      "condition": {
        "field": "documents.sro_certificate.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Участник допускается только со статусом санкционной проверки «clear».",
      "severity": "critical",
      "category": "санкционная проверка",
      "condition": {
        "field": "supplier.sanctions_status",
        "op": "eq",
        "value": "clear"
      }
    },
    {
      "description": "Заявки принимаются не позднее 20 ноября 2026 года.",
      "severity": "critical",
      "category": "срок подачи",
      "condition": {
        "field": "bid.submission_date",
        "op": "le",
        "value": "2026-11-20"
      }
    }
  ]
}

{
  "ruleset_id": "socialnyy-kontrakt",
  "rules": [
    {
      "description": "Домохозяйство должно находиться в Москве или Московской области.",
      "severity": "critical",
      "category": "регион",
      "condition": {
        "field": "household.region",
        "op": "in",
        "value": [
          "Москва",
          "Московская область"
        ]
      }
    },
    {
      "description": "Доход на человека не должен превышать 25000 рублей в месяц.",
      "severity": "critical",
      "category": "доход",
      "condition": {
        "field": "household.monthly_income_per_person_rub",
        "op": "le",
        "value": 25000
      }
    },
    {
      "description": "Требуется согласие на обработку персональных данных.",
      "severity": "critical",
      "category": "согласие",
      "condition": {
        "field": "documents.personal_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявитель должен иметь статус unemployed или job_seeker.",
      "severity": "critical",
      "category": "занятость",
      "condition": {
        "field": "applicant.employment_status",
        "op": "in",
        "value": [
          "unemployed",
          "job_seeker"
        ]
      }
    }
  ]
}
